def amat(hit_l1, miss_l1, hit_l2, miss_l2, mem):
    return hit_l1 + miss_l1 * (hit_l2 + miss_l2 * mem)
# Example: hit_l1=1ns, miss_l1=0.1, hit_l2=3ns, miss_l2=0.05, mem=70ns
print(amat(1,0.1,3,0.05,70))  # -> 5.55 ns

from collections import OrderedDict
class LRUCache:
    def __init__(self, capacity: int):
        self.cache = OrderedDict()
        self.capacity = capacity
    def get(self, key: int) -> int:
        if key not in self.cache: return -1
        self.cache.move_to_end(key)
        return self.cache[key]
    def put(self, key: int, value: int) -> None:
        if key in self.cache: self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity: self.cache.popitem(last=False)

from collections import deque
class FIFOCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.queue = deque()
        self.set = set()
    def access(self, page):
        if page not in self.set:
            if len(self.queue) >= self.capacity:
                evicted = self.queue.popleft()
                self.set.remove(evicted)
            self.queue.append(page)
            self.set.add(page)

