def amdahl_speedup(p, s):
    return 1.0 / ((1.0 - p) + (p / s))
print(amdahl_speedup(0.8, 4)) # Output: 2.5

def max_amdahl_speedup(p):
    return 1.0 / (1.0 - p)
print(max_amdahl_speedup(0.9)) # Output: 10.0

